"""Generate src/Generated.h from the sheets: one constexpr struct per row. Run preflight first."""
import json, pathlib, sys
root = pathlib.Path(__file__).parent.parent
S = {json.load(open(p))['sheet']: json.load(open(p)) for p in sorted((root / 'sheets').glob('*.json'))}
def row(s, i): return next(r for r in S[s]['rows'] if r['id'] == i)
def cs(x): return json.dumps(x)
def hexid(x): return int(x, 16)
out = ['// GENERATED by tools/gen.py from sheets/*.json. Edit the sheets, not this file.', '#pragma once', '#include <array>', '#include <cstdint>', '#include <string_view>', '', 'namespace bo3z::gen', '{']
out.append('\tstruct FormRef { std::string_view plugin; std::uint32_t localId; std::string_view editorId; };')
# rounds
r = row('rounds', 'night_rounds')
out.append(f'\tinline constexpr float kChaseRelocateDist = {float(r["chaseRelocateDist"])}f, kChaseRelocateSeconds = {float(r["chaseRelocateSeconds"])}f, kChaseStallSeconds = {float(r["chaseStallSeconds"])}f;')
out.append(f'\tinline constexpr float kCycleMinutes = {float(r["cycleMinutes"])}f;  // a full Skyrim day; night is nightStart..nightEnd (20:00-05:36 = 40%)')
out.append(f'\tinline constexpr float kManaRegenPerSecond = {float(r["manaRegenPerSecond"])}f, kManaRegenDelay = {float(r["manaRegenDelay"])}f;')
out.append(f'\tinline constexpr bool kZombieMeleeWeapons = {str(r["zombieWeapons"] == "melee").lower()};  // keep swords/axes/maces; strip bows, staves, spells')
out.append('\tstruct Rounds {\n\t\tfloat nightStartHour, nightEndHour, breakSeconds, firstBreakSeconds; int maxAlive, aiMaxBase, aiPerPlayer;\n\t\tstd::array<float, 5> earlyRoundScale; int hpStart, hpLinearPerRound, hpLinearUntil; float hpMultAfter, hpScale;\n\t\tfloat spawnDelayStart, spawnDelayDecay, spawnDelayMin; int specialEveryRounds, specialFirstRound;\n\t\tstd::array<float, 2> spawnRingExterior, spawnRingInterior; float spawnHeightOffset; int maxCorpses; };')
out.append(f'\tinline constexpr Rounds kRounds{{ {r["nightStartHour"]}f, {r["nightEndHour"]}f, {r["breakSeconds"]}f, {r["firstBreakSeconds"]}f, {r["maxAlive"]}, {r["aiMaxBase"]}, {r["aiPerPlayer"]},\n\t\t{{ {", ".join(str(x)+"f" for x in r["earlyRoundScale"])} }}, {r["hpStart"]}, {r["hpLinearPerRound"]}, {r["hpLinearUntil"]}, {r["hpMultAfter"]}f, {r["hpScale"]}f,\n\t\t{r["spawnDelayStart"]}f, {r["spawnDelayDecay"]}f, {r["spawnDelayMin"]}f, {r["specialEveryRounds"]}, {r["specialFirstRound"]},\n\t\t{{ {r["spawnRingExterior"][0]}.f, {r["spawnRingExterior"][1]}.f }}, {{ {r["spawnRingInterior"][0]}.f, {r["spawnRingInterior"][1]}.f }}, {r["spawnHeightOffset"]}.f, {r["maxCorpses"]} }};')
assert r['dawn'] == 'crumble' and r['unfinishedRound'] == 'resume'
q = row('quests', r['pauseUntilQuest'].split(':')[1])
out.append(f'\tinline constexpr FormRef kIntroQuest{{ {cs(q["plugin"])}, 0x{hexid(q["localId"]):06X}, {cs(q["editorId"])} }};')
# enemies
out.append('\tstruct Enemy { std::string_view id, label; FormRef form; bool isLeveledList; int minRound, weight; bool specialRound; std::string_view headNode; bool forceCombat; int bossEvery; bool elite; int kind; float healthMult, speedMult; };')
en = S['enemies']['rows']
out.append(f'\tinline constexpr std::array<Enemy, {len(en)}> kEnemies{{ {{')
sys.path.insert(0, str(root / 'tools')); import esp_ids as _eids; _EIDS, _ = _eids.assign(S)
for e in en:
    out.append(f'\t\tEnemy{{ {cs(e["id"])}, {cs(e["label"])}, {{ {cs(e["plugin"])}, 0x{(_EIDS[("NPC_", e["localId"][5:])] if e["localId"].startswith("auto:") else hexid(e["localId"])):06X}, {cs(e["editorId"])} }}, {str(e["recordType"]=="LVLN").lower()}, {e["minRound"]}, {e["weight"]}, {str(e["specialRound"]).lower()}, {cs(e["headNode"])}, {str(e["forceCombat"]).lower()}, {e.get("bossEvery", 0)}, {str(e.get("elite", False)).lower()}, {["zombie", "reaper", "necro", "minion"].index(e.get("kind", "zombie"))}, {float(e.get("healthMult", 1.0))}f, {float(e.get("speedMult", 1.0))}f }},')
out.append('\t} };')
# sounds
out.append('\tenum class Sound : int {')
snd = S['sounds']['rows']
for i, s in enumerate(snd): out.append(f'\t\t{s["id"]} = {i},')
out.append('\t};')
out.append(f'\tinline constexpr std::array<FormRef, {len(snd)}> kSounds{{ {{')
sys.path.insert(0, str(root / 'tools')); import esp_ids as _ids; _SIDS, _ = _ids.assign(S)
for s in snd: out.append(f'\t\tFormRef{{ {cs(s["plugin"])}, 0x{(_SIDS[("SNDR", s["id"])] if s["localId"] == "auto" else hexid(s["localId"])):06X}, {cs(s["editorId"])} }},')
out.append('\t} };')
# economy
for e in S['economy']['rows']: out.append(f'\tinline constexpr int kPoints_{e["id"]} = {e["points"]};  // {e["event"]}')
# input
for i in S['input']['rows']: out.append(f'\tinline constexpr std::uint32_t kKey_{i["id"]} = {i["code"]};  // {i["device"]}: {i["action"]}')
out.append(f'\tinline constexpr bool kFireIsMouse = {str(row("input","fire")["device"]=="mouse").lower()};')
# persistence
for p in S['persistence']['rows']: out.append(f'\tinline constexpr int kAV_{p["id"]} = /*{p["actorValue"]}*/ {68 + int(p["actorValue"][-2:]) - 1};')
# hud
out.append('\tstruct HudItem { std::string_view id; int anchor; float ox, oy, fontPx; std::uint32_t rgba; };')
anchors = {'bottom_left':0,'bottom_right':1,'center':2,'top_center':3,'bottom_center':4}
for h in S['hud']['rows']:
    c = int(h['color'][1:], 16)
    out.append(f'\tinline constexpr HudItem kHud_{h["id"]}{{ {cs(h["id"])}, {anchors[h["anchor"]]}, {h["offset"][0]}.f, {h["offset"][1]}.f, {h["fontPx"]}.f, 0x{(c<<8)|0xFF:08X} }};')
out.append('}')
(root / 'src').mkdir(exist_ok=True)
(root / 'src/Generated.h').write_text('\n'.join(out) + '\n')
print('wrote src/Generated.h', len(out), 'lines')

# ---------------- v0.2 tables (appended to Generated.h) ----------------
import esp_ids
def F(v): return repr(float(v)) + 'f'
IDS, _ = esp_ids.assign(S)
o = ['', '// ---- v0.2 ----', '#include <string_view>', 'namespace bo3z::gen', '{',
     f'\tinline constexpr std::string_view kPlugin = {cs(esp_ids.PLUGIN)};']
fires = {'semi': 0, 'auto': 1, 'burst': 2, 'pump': 3}
o.append('\tenum class Fire : int { Semi = 0, Auto = 1, Burst = 2, Pump = 3 };')
o.append('\tenum class Special : int { None = 0, Splash, Chain, Cone, Wabbajack, Poison, Soul, Slow, Lifesteal, Stagger, Pierce, Stasis, Hex, Plague, Daze };')
o.append('\tinline constexpr int kKindWand = 0, kKindTome = 1, kKindWonder = 2, kKindBow = 3;')
o.append(f'\tinline constexpr std::uint32_t kWandCastEffect = 0x{IDS[("MGEF", "wandcast")]:03X};')
import json as _json
BL = sorted(q.stem for q in (root / 'tools/templates/expl').glob('*.json'))
o.append('\t// spell blasts: Skyrim.esm explosions cloned at runtime with no damage (tools/templates/expl)')
o.append('\tinline constexpr std::array<std::pair<std::string_view, std::uint32_t>, ' + str(len(BL)) + '> kBlasts{ {' + ', '.join('{ "%s", 0x%06X }' % (b, int(_json.load(open(root / 'tools/templates/expl' / (b + '.json')))['formid'], 16)) for b in BL) + '} };')
o.append('\tstruct GunDef { std::string_view id, label, cls; Fire fire; float damage, headMult; int pellets; float spreadHip, spreadAds; int clip, reserve, fireDelayMs, burst, reloadMs; float range, splashRadius, splashDamage, hitRadius, headRadius; Sound fireSnd, reloadSnd, emptySnd; int wallBuyCost, ammoCost, boxWeight; std::uint32_t weapId; int special, spell, spellOn; bool retired; std::uint32_t bulletSpell; int kind; float mana, abilityValue; std::uint32_t handSpell; std::string_view abilityText; std::uint32_t color; std::string_view chargeName, chargeText; float chargeSeconds, chargeCooldown, chargeMana; int chargeStyle; int tapBlast, chargeBlast; int chargeAura, chargeSpell; std::uint32_t ammo; Sound chargeSnd; int relicTown; int handLook; };')
o.append('\tenum ChargeStyle : int { kThrust = 0, kSlam = 1, kSweep = 2, kTwirl = 3, kRaise = 4, kSurge = 5 };')
W = S['weapons']['rows']
sid = lambda v: 'Sound::' + v.split(':')[1]
RELIC_TOWNS = []
for _l in S['locations']['rows']:
    if _l['town'] not in RELIC_TOWNS: RELIC_TOWNS.append(_l['town'])
SP = S['spells']['rows']
specials = {'none': 0, 'splash': 1, 'chain': 2, 'cone': 3, 'wabbajack': 4, 'poison': 5, 'soul': 6, 'slow': 7, 'lifesteal': 8, 'stagger': 9, 'pierce': 10, 'stasis': 11, 'hex': 12, 'plague': 13, 'daze': 14}
wkinds = {'wand': 0, 'tome': 1, 'wonder': 2, 'bow': 3}
spellon = {'none': 0, 'hit': 1, 'fire': 2, 'every4': 3}
spidx = lambda v: -1 if v == 'none' else [s['id'] for s in SP].index(v.split(':')[1])
o.append(f'\tinline constexpr std::array<FormRef, {len(SP)}> kSpells{{ {{')
for s in SP: o.append(f'\t\tFormRef{{ {cs(s["plugin"])}, 0x{int(s["localId"], 16):06X}, {cs(s["editorId"])} }},')
o.append('\t} };')
for i, s in enumerate(SP): o.append(f'\tinline constexpr int kSpell_{s["id"]} = {i};')
o.append(f'\tinline constexpr std::array<GunDef, {len(W)}> kGuns{{ {{')
for w in W:
    o.append(f'\t\tGunDef{{ {cs(w["id"])}, {cs(w["label"])}, {cs(w["class"])}, Fire({fires[w["fire"]]}), {F(w["damage"])}, {F(w["headMult"])}, {w["pellets"]}, {F(w["spreadHip"])}, {F(w["spreadAds"])}, {w["clip"]}, {w["reserve"]}, {w["fireDelayMs"]}, {w["burst"]}, {w["reloadMs"]}, {F(w["range"])}, {F(w["splashRadius"])}, {F(w["splashDamage"])}, {F(w["hitRadius"])}, {F(w["headRadius"])}, {sid(w["fireSound"])}, {sid(w["reloadSound"])}, {sid(w["emptySound"])}, {w["wallBuyCost"]}, {w["ammoCost"]}, {w["boxWeight"]}, 0x{IDS[("WEAP", w["id"])]:03X}, {specials[w["special"]]}, {spidx(w["spell"])}, {spellon[w["spellOn"]]}, {str(w.get("retired", False)).lower()}, 0x{(IDS[("SPEL", "bullet_" + w["projectile"])] if w.get("projectile", "none") != "none" else 0):03X}, {wkinds[w["kind"]]}, {F(w["mana"])}, {F(w["abilityValue"])}, 0x{(IDS[("SPEL", "hand_" + w["id"])] if w["kind"] in ("tome", "wonder") else 0):03X}, {cs(w["abilityText"])}, 0x{w["element"]}, {cs(w["chargeName"])}, {cs(w["chargeText"])}, {F(w["chargeSeconds"])}, {F(w["chargeCooldown"])}, {F(w["chargeMana"])}, {["thrust","slam","sweep","twirl","raise","surge"].index(w["chargeStyle"])}, {BL.index(w["tapBlast"])}, {BL.index(w["chargeBlast"])}, {spidx("spells:aura_" + w["chargeAura"])}, {spidx(w["chargeSpell"] if w["chargeSpell"] == "none" else "spells:" + w["chargeSpell"])}, 0x{(IDS[("AMMO", "arrow_" + w["id"])] if w["kind"] == "bow" else 0):03X}, {sid(w["chargeSound"])}, {RELIC_TOWNS.index(w["relicTown"]) if w["relicTown"] != "none" else -1}, {spidx(w.get("handLook", "none"))} }},')
o.append('\t} };')
for i, w in enumerate(W): o.append(f'\tinline constexpr int kGunIdx_{w["id"]} = {i};')
